CREATE TABLE users(id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('CUSTOMER','SELLER','ADMIN')),active BOOLEAN NOT NULL DEFAULT true,auth_version INT NOT NULL DEFAULT 0);
CREATE TABLE stores(id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES users,name TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE categories(id BIGSERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE products(id BIGSERIAL PRIMARY KEY,seller_id BIGINT REFERENCES stores NOT NULL,category_id BIGINT REFERENCES categories NOT NULL,title TEXT NOT NULL,brand TEXT NOT NULL,description TEXT NOT NULL,image TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INT NOT NULL DEFAULT 0);
CREATE INDEX product_search ON products USING GIN(to_tsvector('english',title || ' ' || brand || ' ' || description));
CREATE TABLE variants(id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products,sku TEXT UNIQUE NOT NULL,color TEXT NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>0),original_price NUMERIC(12,2) NOT NULL,stock INT NOT NULL CHECK(stock>=0),reserved INT NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),threshold INT NOT NULL DEFAULT 5);
CREATE TABLE addresses(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users,name TEXT NOT NULL,line1 TEXT NOT NULL,city TEXT NOT NULL,state TEXT NOT NULL,zip TEXT NOT NULL);
CREATE TABLE cart_items(user_id BIGINT REFERENCES users,variant_id BIGINT REFERENCES variants,quantity INT NOT NULL CHECK(quantity BETWEEN 1 AND 20),PRIMARY KEY(user_id,variant_id));
CREATE TABLE wishlists(user_id BIGINT REFERENCES users,product_id BIGINT REFERENCES products,PRIMARY KEY(user_id,product_id));
CREATE TABLE promotions(code TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('PERCENT','FIXED')),amount NUMERIC(12,2) NOT NULL CHECK(amount>0),minimum NUMERIC(12,2) NOT NULL DEFAULT 0,max_discount NUMERIC(12,2) NOT NULL DEFAULT 100,starts TIMESTAMPTZ NOT NULL,ends TIMESTAMPTZ NOT NULL,usage_limit INT NOT NULL DEFAULT 100,used INT NOT NULL DEFAULT 0,per_user INT NOT NULL DEFAULT 1);
CREATE TABLE orders(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users NOT NULL,idempotency_key TEXT NOT NULL,payment_state TEXT NOT NULL DEFAULT 'PENDING',subtotal NUMERIC(12,2) NOT NULL,discount NUMERIC(12,2) NOT NULL,tax NUMERIC(12,2) NOT NULL,shipping NUMERIC(12,2) NOT NULL,total NUMERIC(12,2) NOT NULL,currency TEXT NOT NULL DEFAULT 'USD',coupon TEXT REFERENCES promotions,address JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ NOT NULL DEFAULT now()+ interval '10 minutes',UNIQUE(user_id,idempotency_key));
CREATE INDEX orders_user ON orders(user_id,created_at DESC);
CREATE TABLE seller_orders(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders,seller_id BIGINT NOT NULL REFERENCES stores,fulfillment TEXT NOT NULL DEFAULT 'PROCESSING',tracking TEXT,UNIQUE(order_id,seller_id));
CREATE TABLE order_items(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders,seller_order_id BIGINT NOT NULL REFERENCES seller_orders,variant_id BIGINT REFERENCES variants,product_id BIGINT REFERENCES products,title TEXT NOT NULL,sku TEXT NOT NULL,color TEXT NOT NULL,seller_name TEXT NOT NULL,image TEXT NOT NULL,quantity INT NOT NULL,unit_price NUMERIC(12,2) NOT NULL,discount NUMERIC(12,2) NOT NULL,tax NUMERIC(12,2) NOT NULL,shipping NUMERIC(12,2) NOT NULL);
CREATE TABLE reservations(order_id BIGINT REFERENCES orders,variant_id BIGINT REFERENCES variants,quantity INT NOT NULL,state TEXT NOT NULL DEFAULT 'HELD',PRIMARY KEY(order_id,variant_id));
CREATE TABLE inventory_ledger(id BIGSERIAL PRIMARY KEY,variant_id BIGINT REFERENCES variants,order_id BIGINT REFERENCES orders,delta INT NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE payment_events(event_id TEXT PRIMARY KEY,order_id BIGINT REFERENCES orders,outcome TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE redemptions(order_id BIGINT PRIMARY KEY REFERENCES orders,user_id BIGINT REFERENCES users,code TEXT REFERENCES promotions);
CREATE TABLE returns(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders,seller_order_id BIGINT UNIQUE REFERENCES seller_orders,reason TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'REQUESTED',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE refunds(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders,seller_order_id BIGINT UNIQUE REFERENCES seller_orders,amount NUMERIC(12,2) NOT NULL,state TEXT NOT NULL DEFAULT 'SUCCEEDED',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users,product_id BIGINT REFERENCES products,rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),title TEXT NOT NULL,body TEXT NOT NULL,visible BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,product_id));
CREATE TABLE outbox(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users,message TEXT NOT NULL,processed BOOLEAN NOT NULL DEFAULT false,attempts INT NOT NULL DEFAULT 0,error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications(id BIGSERIAL PRIMARY KEY,outbox_id BIGINT UNIQUE REFERENCES outbox,user_id BIGINT REFERENCES users,message TEXT NOT NULL,seen BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id BIGSERIAL PRIMARY KEY,actor BIGINT REFERENCES users,action TEXT NOT NULL,resource TEXT NOT NULL,summary TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE password_resets(token TEXT PRIMARY KEY,user_id BIGINT REFERENCES users,expires TIMESTAMPTZ NOT NULL);
